template <class T, class F>
void unfold(T seed, const F& step, const std::function<void(const T&)>& sink) {
    while (true) {                        // step: (T, T&) -> bool, false = stop
        sink(seed);                       // emit one layer
        T next;
        if (!step(seed, next)) return;    // termination lives in the step function
        seed = next;                      // next seed, by value
    }
}
unfold(8, [](int n, int& out) { if (n <= 1) return false; out = n / 2; return true; },
       [](int n) { std::cout << n << ' '; });

