struct unfold_cursor {                  // pull-style generator object (no coroutines)
    int state;
    explicit unfold_cursor(int seed) : state(seed) {}
    bool valid() const { return state > 1; }   // stop condition
    int current() const { return state; }
    void advance() { state /= 2; }              // one step: next seed
};
for (unfold_cursor c{8}; c.valid(); c.advance()) std::cout << c.current() << ' ';  // 8 4 2

std::generator<int> countdown(int seed) {
    for (int s = seed; s > 1; s /= 2) {
        co_yield s;                     // one layer per resume
    }
}
for (int v : countdown(8)) std::cout << v << ' ';
